const up = s => s.charAt(0).toUpperCase() + s.slice(1);
const after = (s, sep) => up(s.slice(s.indexOf(sep) + sep.length));
const sec = (t, c, o = {}) => ({ t, c: [].concat(c), id: o.id, lead: o.lead });
const dl = (arr) => h('dl', { class: 'dl' }, arr.map(([a, b]) => h('div', null, h('dt', null, a), h('dd', null, rich(b)))));
const Badge = k => { const m = { ok: 'cumprido, com atraso', trav: 'travado', pont: 'pontual e isolado', rev: 'revertido', papel: 'só no papel', sem: 'sem balanço registrado', parc: 'incompleto' }; return h('span', { class: 'badge b-' + k }, m[k]); };
const Board = lanes => h('div', { class: 'board' }, lanes.map(l => h('div', { class: 'lane b-' + l.k }, h('h4', null, Badge(l.k)), l.note ? h('p', { class: 'note' }, l.note) : null,
  h('ul', null, l.items.map(it => h('li', { tabindex: 0 }, h('strong', null, it.t), it.d ? h('span', null, rich(txt(it.d))) : null, it.go ? A(it.go) : null))))));
const Prop = (items) => h('div', { class: 'props' }, items.map(it => h('article', { class: 'prop' }, h('header', null, h('h4', null, it.t), it.s ? Badge(it.s) : null), P(it.d))));
