/* sem travessões: troca por vírgula/dois-pontos nos textos exibidos */
(() => {
  const fix = s => s.replace(/\s+[—–]\s+/g, (m, off, str) => (/[:.;!?]$/.test(str.slice(0, off)) ? ' ' : ', ')).replace(/[—–]/g, (m, off, str) => /\d/.test(str[off - 1] || '') && /\d/.test(str[off + 1] || '') ? '-' : ', ');
  const TITLE = 'h1,h2,h3,h4,h5,h6,.cell-t,.pb-t b,.pb-t small,.tl-t,.chip,.an-tile span,.an-band span,.an-ph-c strong,.sys-c strong,.mx-tab,.leg-b,.g-steps strong,.legend h3,.qa-q,.agent strong,.pg strong,.mx-here b,.sys-out h4,.tab,[role=tab]';
  const capTxt = s => s.replace(/^([\d.\s·]*)([a-zà-ÿ])/i, (m, p, c) => p + c.toUpperCase());
  const capFirst = el => { const tw = document.createTreeWalker(el, NodeFilter.SHOW_TEXT); let t; while ((t = tw.nextNode())) { if (/\S/.test(t.nodeValue)) { const v = capTxt(t.nodeValue); if (v !== t.nodeValue) t.nodeValue = v; return; } } };
  const walk = n => {
    if (n.nodeType === 3) {
      if (/[—–]/.test(n.nodeValue)) n.nodeValue = fix(n.nodeValue);
      const pe = n.parentNode;
      if (pe && pe.namespaceURI === 'http://www.w3.org/2000/svg' && (pe.tagName === 'text' || (pe.tagName === 'tspan' && pe.parentNode.firstElementChild === pe)) && /\S/.test(n.nodeValue) && !pe.closest('.ax')) { const v = capTxt(n.nodeValue); if (v !== n.nodeValue) n.nodeValue = v; }
      if (pe && pe.nodeType === 1 && pe.matches && pe.matches(TITLE)) capFirst(pe);
      return;
    }
    if (n.nodeType !== 1 || /^(SCRIPT|STYLE)$/.test(n.tagName)) return;
    if (n.hasAttribute && n.hasAttribute('aria-label')) { const v = n.getAttribute('aria-label'); if (/[—–]/.test(v)) n.setAttribute('aria-label', fix(v)); }
    if (n.hasAttribute && n.hasAttribute('data-full')) { const v = n.getAttribute('data-full'); if (/[—–]/.test(v)) n.setAttribute('data-full', fix(v)); }
    if (n.matches && n.matches(TITLE)) capFirst(n);
    n.childNodes.forEach(walk);
  };
  const SEL = 'h1,h2,h3,h4,h5,.cell-t,.pb-t b,.pb-t small,.tl-t,.sys-c strong,.sys-tag,.an-tile span,.an-band span,.an-ph-c strong,.chip,.mx-tab,.pg strong,.neb-info b,.listv a,.listv h2,.qa-q,.cy-info strong,.rings-out strong,.g-steps strong,.legend h3,.agent strong,.steps strong,.tnl,.leg-b,.sec-lab text,.brand,.callout-t,.mini-n text';
  const capEl = el => {
    const w = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
    for (let t = w.nextNode(); t; t = w.nextNode()) {
      const m = /\p{L}/u.exec(t.nodeValue); if (!m) continue;
      const c = t.nodeValue[m.index], u = c.toLocaleUpperCase('pt-BR');
      if (c !== u) t.nodeValue = t.nodeValue.slice(0, m.index) + u + t.nodeValue.slice(m.index + 1);
      return;
    }
  };
  const capAll = n => { if (n.nodeType !== 1) n = n.parentElement; if (!n) return; const own = n.closest && n.closest(SEL); if (own) capEl(own); if (n.querySelectorAll) n.querySelectorAll(SEL).forEach(capEl); };
  walk(document.body); capAll(document.body);
  new MutationObserver(ms => ms.forEach(m => { m.addedNodes.forEach(x => { walk(x); capAll(x); }); if (m.type === 'characterData') { walk(m.target); capAll(m.target); } })).observe(document.body, { childList: true, characterData: true, subtree: true });
  const fixT = s => fix(s).replace(/^(\d+(?:\.\d+)?\s*)(\p{Ll})/u, (m, d, c) => d + c.toLocaleUpperCase('pt-BR')); const t = document.title; if (document.title !== fixT(t)) document.title = fixT(t);
  new MutationObserver(() => { const v = fixT(document.title); if (v !== document.title) document.title = v; }).observe(document.querySelector('title') || document.head, { childList: true, subtree: true, characterData: true });
})();


